  const a=frame(0),side=frame(.25),again=frame(0),end=frame(1);let lit=0,diff=0,repeat=0,seam=0,saturated=0;for(let i=0;i<a.length;i+=4){if(Math.max(a[i],a[i+1],a[i+2])>30)lit++;if(a[i]>245&&a[i+1]>245&&a[i+2]>245)saturated++;for(let k=0;k<3;k++){diff+=Math.abs(a[i+k]-side[i+k]);repeat+=Math.abs(a[i+k]-again[i+k]);seam+=Math.abs(a[i+k]-end[i+k]);}}
