  const difference=(a,b)=>a.reduce((s,v,i)=>s+(i%4===3?0:Math.abs(v-b[i])),0),a=frame(0),b=frame(.25),repeat=frame(0),end=frame(1),before=frame(1-1/240),after=frame(1/240);renderer.dispose();return{motion:difference(a,b),repeat:difference(a,repeat),seam:difference(a,end),lastStep:difference(before,a),firstStep:difference(a,after)};
