 await page.locator('#phase').fill('0.125');await page.locator('#phase').dispatchEvent('input');const baseAzimuth=Number(await page.locator('#azimuth').inputValue());await page.locator('#motion').selectOption('still');assert.ok(Math.abs(Number(await page.locator('#azimuth').inputValue())-baseAzimuth-45)<.01);assert.equal(await page.locator('#phase').inputValue(),'0.125');await page.locator('#hide').click();assert.equal(await page.locator('aside').isVisible(),false);await page.locator('#show').click();assert.equal(await page.locator('aside').isVisible(),true);log('Still camera and clean view');
 await page.locator('summary',{hasText:'Capture the light'}).click();await page.locator('#link').click();await page.waitForFunction(()=>document.querySelector('#status').textContent.includes('Scene link')||document.querySelector('#status input'));log('Scene replay link');await page.locator('#reset').click();
