 const decoded=execFileSync('ffmpeg',['-v','error','-i',videoPath,'-vf','select=eq(n\\,0)+eq(n\\,60)','-vsync','0','-f','rawvideo','-pix_fmt','rgb24','pipe:1'],{maxBuffer:8*1024*1024});const n=720*720*3;assert.equal(decoded.length,2*n);let change=0;for(let i=0;i<n;i++)change+=Math.abs(decoded[i]-decoded[n+i]);assert.ok(change/n>1);log('Decoded MP4 visibly animates with the camera held still');
