 await page.goto(base+'/#scene=chen-orbit');await page.locator('#frame-host iframe').waitFor();assert.equal(await page.locator('#frame-host iframe').count(),1);await page.locator('#back').click();assert.equal(await page.locator('#frame-host iframe').count(),0);await page.locator('a.cover[href="#scene=chen-orbit"]').click();await page.locator('#frame-host iframe').waitFor();assert.equal(await page.locator('#frame-host iframe').count(),1);log('Atlas launch, destroy and reopen');const noGPU=await browser.newContext();await noGPU.addInitScript(()=>{const original=HTMLCanvasElement.prototype.getContext;HTMLCanvasElement.prototype.getContext=function(type,...args){return type==='webgl2'?null:original.call(this,type,...args);};});const fallback=await noGPU.newPage();await fallback.goto(study);assert.equal(await fallback.locator('#error').isVisible(),true);assert.equal(await fallback.locator('#record').isEnabled(),false);log('Visible unsupported-WebGL message');
